#include <assert.h>
#include <stdint.h>
int64_t slang_ggml_str_reset(void);
int64_t slang_ggml_str_push(int64_t);
int64_t slang_ggml_backend_init(void);
int64_t slang_ggml_model_load(int64_t);
int64_t slang_ggml_ctx_create(int64_t);
int64_t slang_ggml_tokenize(int64_t);
int64_t slang_ggml_token_at(int64_t);
int64_t slang_ggml_prefix_prepare(void);
int64_t slang_ggml_eval_prompt(void);
int64_t slang_ggml_eval(int64_t);
int64_t slang_ggml_sample(void);
int64_t slang_ggml_is_eog(int64_t);
int64_t slang_ggml_piece(int64_t);
int64_t slang_ggml_out_len(void);
int64_t slang_ggml_out_byte(int64_t);
int64_t slang_ggml_n_ctx(void);
int64_t slang_ggml_kv_clear(void);
int64_t slang_ggml_prefix_hits(void);
int64_t slang_ggml_prefix_misses(void);
int64_t slang_ggml_prefix_tokens_reused(void);
int64_t slang_ggml_prefix_tokens_prefilled(void);
int64_t slang_ggml_prefix_cache_configure(int64_t, int64_t);
int64_t slang_ggml_prefix_admissions(void);
int64_t slang_ggml_prefix_evictions(void);
int64_t slang_ggml_prefix_resident_entries(void);
int64_t slang_ggml_prefix_resident_bytes(void);
int64_t slang_ggml_prefix_rejected_bytes(void);
int64_t slang_ggml_prefix_restore_failures(void);
int64_t slang_ggml_capabilities(void);
int64_t slang_ggml_free(void);
int64_t slang_ggml_request_configure(int64_t);
int64_t slang_ggml_request_create(int64_t);
int64_t slang_ggml_request_close(int64_t);
int64_t slang_ggml_request_cancel(int64_t);
int64_t slang_ggml_request_str_reset(int64_t);
int64_t slang_ggml_request_str_push(int64_t, int64_t);
int64_t slang_ggml_request_tokenize(int64_t, int64_t);
int64_t slang_ggml_request_prefix_prepare(int64_t);
int64_t slang_ggml_request_eval_prompt(int64_t);
int64_t slang_ggml_request_eval(int64_t, int64_t);
int64_t slang_ggml_request_sample(int64_t);
int64_t slang_ggml_request_token_at(int64_t, int64_t);
int64_t slang_ggml_request_kv_clear(int64_t);
int64_t slang_ggml_request_n_ctx(int64_t);
int64_t slang_ggml_request_piece(int64_t, int64_t);
int64_t slang_ggml_request_out_len(int64_t);
int64_t slang_ggml_request_out_byte(int64_t, int64_t);
void mock_llama_fail_restore_once(void);
void mock_llama_fail_remove_once(void);
void mock_llama_fail_serialize_once(void);
void mock_llama_fail_decode_once(void);
static void text(const char *s) { slang_ggml_str_reset(); while (*s) slang_ggml_str_push((unsigned char)*s++); }
static void prefill(const char *s, int64_t expected_start) {
    text(s);
    assert(slang_ggml_tokenize(1) > 0);
    assert(slang_ggml_prefix_prepare() == expected_start);
    assert(slang_ggml_eval_prompt() > 0);
}
static void request_text(int64_t handle, const char *s) {
    assert(slang_ggml_request_str_reset(handle) == 0);
    while (*s) assert(slang_ggml_request_str_push(handle, (unsigned char)*s++) > 0);
}
static void request_prefill(int64_t handle, const char *s, int64_t expected_start) {
    request_text(handle, s);
    assert(slang_ggml_request_tokenize(handle, 1) > 0);
    assert(slang_ggml_request_prefix_prepare(handle) == expected_start);
    assert(slang_ggml_request_eval_prompt(handle) > 0);
}
int main(void) {
    assert(slang_ggml_ctx_create(64) < 0);
    assert(slang_ggml_request_create(64) < 0);
    assert(slang_ggml_request_close(1) < 0);
    assert(slang_ggml_request_cancel(1) < 0);
    assert(slang_ggml_request_configure(0) < 0);
    assert(slang_ggml_request_configure(9) < 0);
    slang_ggml_backend_init(); text("model"); assert(slang_ggml_model_load(0) == 0);
    assert(slang_ggml_ctx_create(64) == 0); assert(slang_ggml_capabilities() == 31);
    assert(slang_ggml_ctx_create(64) < 0);
    assert(slang_ggml_model_load(0) < 0);
    assert(slang_ggml_n_ctx() == 64);
    assert(slang_ggml_prefix_cache_configure(2, 1024) == 2);
    assert(slang_ggml_prefix_cache_configure(9, 1024) < 0);
    prefill("abc", 0);
    assert(slang_ggml_token_at(0) == 1);
    assert(slang_ggml_token_at(-1) < 0);
    assert(slang_ggml_piece('Q') == 1);
    assert(slang_ggml_out_len() == 1);
    assert(slang_ggml_out_byte(0) == 'Q');
    assert(slang_ggml_out_byte(1) < 0);
    assert(slang_ggml_eval('R') == 0);
    assert(slang_ggml_sample() == 2);
    assert(slang_ggml_kv_clear() == 0);
    prefill("xyz", 0);
    assert(slang_ggml_prefix_resident_entries() == 2);
    assert(slang_ggml_prefix_resident_bytes() == 48);
    prefill("abcQ", 3);
    assert(slang_ggml_prefix_evictions() == 1);
    prefill("xyz", 0);
    prefill("abcQZ", 4);
    prefill("abcQZ", 5);
    assert(slang_ggml_prefix_hits() == 3);
    assert(slang_ggml_prefix_misses() == 3);
    assert(slang_ggml_prefix_tokens_reused() == 12);
    assert(slang_ggml_prefix_tokens_prefilled() == 17);
    assert(slang_ggml_prefix_admissions() == 5);
    assert(slang_ggml_prefix_evictions() == 3);
    assert(slang_ggml_prefix_resident_entries() == 2);
    assert(slang_ggml_prefix_restore_failures() == 0);
    assert(slang_ggml_prefix_cache_configure(2, 4) == 2);
    assert(slang_ggml_prefix_resident_entries() == 0);
    assert(slang_ggml_prefix_evictions() == 5);
    prefill("z", 0);
    assert(slang_ggml_prefix_rejected_bytes() == 16);
    assert(slang_ggml_prefix_resident_entries() == 0);

    assert(slang_ggml_prefix_cache_configure(2, 1024) == 2);
    int64_t admissions = slang_ggml_prefix_admissions();
    mock_llama_fail_serialize_once();
    prefill("ser", 0);
    assert(slang_ggml_prefix_admissions() == admissions);
    assert(slang_ggml_prefix_resident_entries() == 0);

    prefill("abc", 0);
    mock_llama_fail_restore_once();
    prefill("abcX", 0);
    assert(slang_ggml_prefix_restore_failures() == 1);
    assert(slang_ggml_prefix_resident_entries() == 1);

    mock_llama_fail_remove_once();
    prefill("abcXY", 0);
    assert(slang_ggml_prefix_restore_failures() == 2);
    assert(slang_ggml_prefix_resident_entries() == 1);

    text("abcXYZ");
    assert(slang_ggml_tokenize(1) == 7);
    assert(slang_ggml_prefix_prepare() == 5);
    mock_llama_fail_decode_once();
    assert(slang_ggml_eval_prompt() < 0);
    prefill("isolated", 0);

    admissions = slang_ggml_prefix_admissions();
    assert(slang_ggml_prefix_cache_configure(0, 1024) == 0);
    prefill("disabled", 0);
    assert(slang_ggml_prefix_admissions() == admissions);
    assert(slang_ggml_prefix_resident_entries() == 0);

    assert(slang_ggml_request_configure(3) == 3);
    int64_t first = slang_ggml_request_create(32);
    int64_t second = slang_ggml_request_create(48);
    assert(first > 0 && second > 0 && first != second);
    assert(slang_ggml_request_create(32) < 0);
    assert(slang_ggml_request_configure(1) < 0);
    assert(slang_ggml_request_n_ctx(first) == 32);
    assert(slang_ggml_request_n_ctx(second) == 48);
    request_text(first, "first");
    request_text(second, "second");
    assert(slang_ggml_request_tokenize(first, 1) == 6);
    assert(slang_ggml_request_tokenize(second, 1) == 7);
    assert(slang_ggml_request_token_at(first, 0) == 1);
    assert(slang_ggml_request_token_at(first, 99) < 0);
    assert(slang_ggml_request_piece(first, 'A') == 1);
    assert(slang_ggml_request_piece(second, 'B') == 1);
    assert(slang_ggml_request_out_len(first) == 1);
    assert(slang_ggml_request_out_byte(first, 0) == 'A');
    assert(slang_ggml_request_out_byte(second, 0) == 'B');
    assert(slang_ggml_request_prefix_prepare(first) == 0);
    assert(slang_ggml_request_prefix_prepare(second) == 0);
    assert(slang_ggml_request_eval_prompt(first) == 6);
    assert(slang_ggml_request_eval_prompt(second) == 7);
    assert(slang_ggml_request_eval(first, 'C') == 0);
    assert(slang_ggml_request_sample(first) == 2);
    assert(slang_ggml_request_kv_clear(second) == 0);
    assert(slang_ggml_free() < 0);
    assert(slang_ggml_request_close(first) == 0);
    assert(slang_ggml_request_n_ctx(first) < 0);
    int64_t reused = slang_ggml_request_create(24);
    assert(reused > 0 && reused != first);
    assert(slang_ggml_request_n_ctx(first) < 0);
    assert(slang_ggml_request_cancel(reused) == 0);
    assert(slang_ggml_request_close(reused) < 0);
    assert(slang_ggml_request_close(second) == 0);

    assert(slang_ggml_request_configure(4) == 4);
    assert(slang_ggml_prefix_cache_configure(1, 1024) == 1);
    int64_t producer = slang_ggml_request_create(32);
    request_prefill(producer, "pin", 0);
    assert(slang_ggml_request_close(producer) == 0);
    int64_t consumer = slang_ggml_request_create(32);
    request_text(consumer, "pinX");
    assert(slang_ggml_request_tokenize(consumer, 1) == 5);
    assert(slang_ggml_request_prefix_prepare(consumer) == 3);
    int64_t contender = slang_ggml_request_create(32);
    request_prefill(contender, "other", 0);
    assert(slang_ggml_prefix_resident_entries() == 1);
    assert(slang_ggml_request_n_ctx(contender) == 32);
    assert(slang_ggml_request_close(contender) == 0);
    assert(slang_ggml_prefix_cache_configure(0, 0) < 0);
    assert(slang_ggml_request_close(consumer) == 0);
    assert(slang_ggml_prefix_cache_configure(0, 0) == 0);
    assert(slang_ggml_free() == 0);
    assert(slang_ggml_n_ctx() < 0);
    assert(slang_ggml_is_eog(2) < 0);
    assert(slang_ggml_request_token_at(first, 0) < 0);
    assert(slang_ggml_request_eval(first, 1) < 0);
    assert(slang_ggml_request_sample(first) < 0);
    assert(slang_ggml_request_kv_clear(first) < 0);
    assert(slang_ggml_prefix_hits() == 0);
    assert(slang_ggml_prefix_resident_bytes() == 0);
    return 0;
}
